/// Static per-joker data: shop/pool identity only (no effects).
#[derive(Debug, Clone, Copy)]
pub struct JokerMeta {
    pub id: JokerId,
    pub key: &'static str,
    pub name: &'static str,
    /// `center.rarity`: 1 common, 2 uncommon, 3 rare, 4 legendary.
    pub rarity: u8,
    pub cost: i64,
    /// `center.unlocked` as shipped (fresh profile). The sim's default
    /// profile treats everything as unlocked (see `Profile`).
    pub unlocked: bool,
    /// `center.enhancement_gate` — the joker only enters pools while a
    /// playing card with this enhancement exists (common_events.lua:2018-2024).
    pub enhancement_gate: Option<&'static str>,
    /// `center.no_pool_flag`/`yes_pool_flag` — G.GAME.pool_flags gates
    /// (Gros Michel / Cavendish; common_events.lua:2033-2034).
    pub no_pool_flag: Option<&'static str>,
    pub yes_pool_flag: Option<&'static str>,
    /// `center.blueprint_compat` — UI hint only; the actual Blueprint/
    /// Brainstorm copy gating happens per effect branch via the
    /// `context.blueprint` checks in Card:calculate_joker (see jokers/).
    pub blueprint_compat: bool,
    /// `center.perishable_compat` / `center.eternal_compat` — sticker
    /// eligibility (common_events.lua:2135-2145; Green/Purple Stake).
    pub perishable_compat: bool,
    pub eternal_compat: bool,
}

